from __future__ import annotations
from .canonical import with_digest
def build_provenance(binding:dict,request:dict,slice_doc:dict,evidence:dict,decision:dict,report:dict)->dict:
    nodes=[{'node_id':'ACL12_HANDOFF','artifact_type':'ACL12_TO_ACL13','artifact_digest':binding['acl12_handoff_digest']},{'node_id':'ACL13_REQUEST','artifact_type':'ONE_HOUR_ASSESSMENT_REQUEST','artifact_digest':request['assessment_request_digest']},{'node_id':'ACL13_FAST_SLICE','artifact_type':'FAST_DATA_SLICE','artifact_digest':slice_doc['slice_digest']},{'node_id':'ACL13_EVIDENCE','artifact_type':'ONE_HOUR_EVIDENCE_BUNDLE','artifact_digest':evidence['evidence_bundle_digest']},{'node_id':'ACL13_DECISION','artifact_type':'ONE_HOUR_ASSESSMENT_RESULT','artifact_digest':decision['assessment_result_digest']},{'node_id':'ACL13_REPORT','artifact_type':'ONE_HOUR_ASSESSMENT_REPORT','artifact_digest':report['report_digest']}]
    edges=[{'from':'ACL12_HANDOFF','to':'ACL13_REQUEST'},{'from':'ACL13_REQUEST','to':'ACL13_FAST_SLICE'},{'from':'ACL13_FAST_SLICE','to':'ACL13_EVIDENCE'},{'from':'ACL13_EVIDENCE','to':'ACL13_DECISION'},{'from':'ACL13_DECISION','to':'ACL13_REPORT'}]
    return with_digest({'schema_version':'1.0.0','nodes':nodes,'edges':edges,'reaches_acl12_security_readiness':True,'source_security_readiness_reinterpreted':False,'synthetic_reference_disclosed':request.get('synthetic_reference_data',False),'validation_evidence_invented':False,'production_security_evidence_invented':False,'runtime_candidate_invented':False,'pilot_execution_authority_created':False,'live_order_authority_created':False,'capital_authority_created':False},'graph_digest')
